import { Logout } from '@mesx/common-ui-lib';
import { createRouter, createWebHistory } from 'vue-router';
import pickingScreenView from '../modules/buffer-screen/views/BufferScreenView.vue';
import unauthorized from '../modules/buffer-screen/views/Unauthorized.vue';
import loadingComponent from '../modules/buffer-screen/views/loading.vue';
import { useProfileStore } from '@/modules/buffer-screen/store/user-auth-store.ts';
import appLogger from '@/utils/logger/app-logger.ts';

const routes = [
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
        router.push('/wkint-ui');
      },
    },
  },
  {
    component: pickingScreenView,
    meta: { requiresAuth: true, title: 'Buffer Monitoring' },

    name: 'wkint-ui',
    path: '/wkint-ui',
  },
  {
    component: unauthorized,

    name: 'Unauthorized',
    path: '/unauthorized',
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
];

export const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  const userAuth = useProfileStore();

  // Check if the route requires authentication
  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.authorizeUser();
        await userAuth.fetchUserAttributes();
      } else {
        // Handle the case where the user is null
        console.error('User not found');
        return next('/unauthorized'); // Return is added here
      }

      // Proceed to the route
      return next(); // Explicit return added
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next('/unauthorized'); // Return is added here
    }
  } else {
    return next(); // Explicit return for non-authenticated routes
  }
});

