export const getUserAttributesByUserId = async (
  userId: number,
): Promise<Array<UserAttribute>> => {
  try {
    const response = await axios.get(
      `${umeBaseUrl}/user-attribute-mapping/${userId}`,
      {
        headers: {
          authorization: `Bearer ${token}`,
        },
      },
    );
    const userAttributes = response.data;

    const userAttributesStore = useUserAttributesStore();
    userAttributesStore.setUserAttributes(userAttributes);
    return userAttributes;
  } catch (error) {
    console.error('Error fetching user attributes', error);
    throw error;
  }
};

