const appendCriteria = (
  parameters: URLSearchParams,
  key: string,
  list?: Array<string>,
): void => {
  if (list) {
    for (const item of list) {
      parameters.append(key, item);
    }
    if (list.length === 1) {
      parameters.append(key, '');
    }
  }
};

export const searchOrderBycriteria = async (criteria: {
  actionTypeList?: Array<string>;
  bufferStatusList?: Array<string>;
  shopOrderList?: Array<string>;
  customerList?: Array<string>;
  workcenterList?: Array<string>;
  materialList?: Array<string>;
  destinationLocationList?: Array<string>;
  sourceLocationList?: Array<string>;
  neoStatusList?: Array<string>;
  outboundDeliveryList?: Array<string>;
  startDate?: string;
  endDate?: string;
  page?: number;
  pageSize?: number;
}): Promise<PaginatedBufferResponseDto> => {
  const userAttributesStore = useUserAttributesStore();
  const plant = Number(userAttributesStore.userAttributes.plant);
  const parameters = new URLSearchParams();
  const page = criteria.page && criteria.page > 0 ? criteria.page : 1;
  const pageSize =
    criteria.pageSize && criteria.pageSize > 0
      ? Math.min(criteria.pageSize, 500)
      : 100;
  appendCriteria(parameters, 'actionTypeList', criteria.actionTypeList);
  appendCriteria(parameters, 'bufferStatusList', criteria.bufferStatusList);
  appendCriteria(parameters, 'shopOrderList', criteria.shopOrderList);
  appendCriteria(parameters, 'materialList', criteria.materialList);
  appendCriteria(parameters, 'customerList', criteria.customerList);
  appendCriteria(parameters, 'workcenterList', criteria.workcenterList);
  appendCriteria(
    parameters,
    'destinationLocationList',
    criteria.destinationLocationList,
  );
  appendCriteria(parameters, 'sourceLocationList', criteria.sourceLocationList);

  appendCriteria(parameters, 'neostatusList', criteria.neoStatusList);
  appendCriteria(
    parameters,
    'outboundDeliveryList',
    criteria.outboundDeliveryList,
  );

  if (criteria.startDate) {
    parameters.append('startDate', criteria.startDate);
  }
  if (criteria.endDate) {
    parameters.append('endDate', criteria.endDate);
  }

  parameters.append('page', page.toString());
  parameters.append('pageSize', pageSize.toString());

  const response = await axiosTimezoneInstance.get(
    `${wkIntegrationBase}/wk-integration-backend/getBufferDataByCriteria/${plant}?${parameters.toString()}`,
    {
      headers: {
        authorization: `Bearer ${token}`,
      },
    },
  );
  return response.data as PaginatedBufferResponseDto;
};

