export const saveUserPreferences = async (
  preferences: Array<UserPreference>,
): Promise<string> => {
  /* eslint no-useless-catch: "off" */

  let endpoint = `${umeBaseUrl}/user-preference/save`;
  if (preferences.some((pref) => pref.action === 'FILTER')) {
    endpoint = `${umeBaseUrl}/user-preference/save`;
  } else if (preferences.some((pref) => pref.action === 'HIDE_COL')) {
    endpoint = `${umeBaseUrl}/user-preference/add`;
  }

  const response = await axios.post(endpoint, preferences, {
    headers: {
      authorization: `Bearer ${token}`,
    },
  });
  return response.data;
};

