      this.pageSize = Math.min(data.pageSize ?? this.pageSize, 500);
      const computedMaxPage = Math.max(1, Math.ceil(safeTotal / this.pageSize));
      const requestedPage = data.page ?? this.page;

      this.total = safeTotal;
      this.page = Math.min(Math.max(1, requestedPage), computedMaxPage);

      // Format the material field to remove leading zeros
      for (const row of this.bufferFiltredRows) {
        row.materialNumber = removeLeadingZeros(row.materialNumber);
      }

      // Persist KPI selection state
      this.saveKPISelectionState();

      return this.bufferFiltredRows;
