          this.isFailedBufferKPISelected =
            kpiState.isFailedBufferKPISelected ?? false;
        } catch (error) {
          console.error('Error restoring KPI selection state:', error);
        }
      }
    },

    applyFiltersToBufferRows() {
      const filters = useFiltersStore();
      const criteria = {
        actionTypeList: filters.actionTypesSelected || [],
        bufferStatusList: filters.bufferStatusSelected || [],
        customerList: filters.customersSelected || [],
        destinationLocationList: filters.destinationLocationSelected || [],
        endDate: filters.endDate || '',
        materialList: filters.materialsSelected || [],
        shopOrderList: filters.orderIdSelected.trim()
          ? [filters.orderIdSelected.trim()]
          : [], // Only include if there's a non-empty value
        sourceLocationList: filters.sourceLocationSelected || [],
        startDate: filters.startDate || '',
      };

      const filtered = this.bufferFiltredRows.filter((row: WkOrder) => {
        // Check if orderId is in shopOrderList
        const matchShopOrder =
          criteria.shopOrderList.length === 0 ||
          criteria.shopOrderList.includes(String(row.orderId));

        // Check if customer is in customerList
        const matchCustomer =
          criteria.customerList.length === 0 ||
          criteria.customerList.includes(String(row.customer));

        // Check if materialNumber is in materialList
        const matchMaterial =
          criteria.materialList.length === 0 ||
          criteria.materialList.includes(String(row.materialNumber));

        // Check if destinationLocation is in destinationLocationList
        const matchDestinationLocation =
          criteria.destinationLocationList.length === 0 ||
          criteria.destinationLocationList.includes(row.destinationLocation);

        // Check if sourceLocation is in sourceLocationList
        const matchSourceLocation =
          criteria.sourceLocationList.length === 0 ||
          criteria.sourceLocationList.includes(row.sourceLocation);

        // Check if actionType is in actionTypeList
        const matchActionType =
          criteria.actionTypeList.length === 0 ||
          criteria.actionTypeList.includes(row.actionType);

        // Check if bufferStatus is in bufferStatusList
        const matchBufferStatus =
          criteria.bufferStatusList.length === 0 ||
          criteria.bufferStatusList.includes(row.bufferStatus);

        // Check if startDate matches
        const matchStartDate =
          !criteria.startDate ||
          (row.launchDateTime &&
            row.launchDateTime >= new Date(criteria.startDate));

        // Check if endDate matches
        const matchEndDate =
          !criteria.endDate ||
          (row.launchDateTime &&
            row.launchDateTime <= new Date(criteria.endDate));

        // Combine all conditions (add others as necessary)
        return (
          matchShopOrder &&
          matchCustomer &&
          matchMaterial &&
          matchDestinationLocation &&
          matchSourceLocation &&
          matchActionType &&
          matchBufferStatus &&
          matchStartDate &&
          matchEndDate
        );
      });

      // Optionally format the material field
      for (const row of filtered) {
        row.materialNumber = removeLeadingZeros(row.materialNumber);
      }

      // Update the filtered rows
      this.bufferFiltredRows = filtered;
      this.total = filtered.length;
      this.page = 1;
