import { defineStore } from 'pinia';
import { UserPreference } from '../../../types/user-preference-type.ts';
import { WkOrder } from '../../../types/wk-order-type.ts';
import * as api from '../service/api.ts';
import { useBufferTableStore } from './buffer-table-store.ts';
import { useUserAttributesStore } from './user-profile-store.ts';

const useFiltersStore = defineStore({
  actions: {
    applyUserPreferences(preferences: Array<UserPreference>) {
      for (const preference of preferences) {
        if (preference.action === 'FILTER') {
          const criteria = preference.userCriteria?.split(';');
          if (criteria) {
            for (const criterion of criteria) {
              const [type, values] = criterion.split(':');
              const valueArray = values ? new Proxy(values.split(','), {}) : [];

              switch (type) {
                case 'customer': {
                  this.customersSelected.push(
                    ...valueArray.filter(
                      (value) => !this.customersSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'destination-location': {
                  this.destinationLocationSelected.push(
                    ...valueArray.filter(
                      (value) =>
                        !this.destinationLocationSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'end-date': {
                  this.endDate = values;
                  break;
                }
                case 'material': {
                  this.materialsSelected.push(
                    ...valueArray.filter(
                      (value) => !this.materialsSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'neo-status': {
                  this.neoStatusSelected.push(
                    ...valueArray.filter(
                      (value) => !this.neoStatusSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'buffer-status': {
                  this.bufferStatusSelected.push(
                    ...valueArray.filter(
                      (value) => !this.bufferStatusSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'outbound-delivery': {
                  this.outboundDeliverySelected.push(
                    ...valueArray.filter(
                      (value) => !this.outboundDeliverySelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'source-location': {
                  this.sourceLocationSelected.push(
                    ...valueArray.filter(
                      (value) => !this.sourceLocationSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'action-type': {
                  this.actionTypesSelected.push(
                    ...valueArray.filter(
                      (value) => !this.actionTypesSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'start-date': {
                  this.startDate = values;
                  break;
                }
                case 'work-center': {
                  this.workCentersSelected.push(
                    ...valueArray.filter(
                      (value) => !this.workCentersSelected.includes(value),
                    ),
                  );
                  break;
                }
                case 'order-id': {
                  this.orderIdSelected = values;
                  break;
                }
                default: {
                  break;
                }
              }
            }
          }
        }
        if (preference.action === 'HIDE_COL') {
          this.updateColumnsPreferences(preference);
        }
      }
    },
    async fetchUserPreferences(): Promise<Array<UserPreference>> {
      const userProfile = useUserAttributesStore();
      const plant = Number(userProfile.userAttributes.plant);
      const userId = localStorage.getItem('userId') ?? 'undefined';
      try {
        const preferences =
          await api.fetchUserPreferenceByPlantUserIdAndAppName(
            plant,
            Number(userId),
            'BUFFER-MONITORING',
          );
        this.applyUserPreferences(preferences);

        return preferences;
      } catch (error) {
        console.error('Error fetching preferences:', error);
        return [];
      }
    },
    updateColumnsPreferences(preference: UserPreference) {
      const bufferTableStore = useBufferTableStore();
      const columnsToHide = preference.addData?.split(';');
      bufferTableStore.bufferColumns = bufferTableStore.bufferColumns.map(
        (column) => ({
          ...column,
          visible: columnsToHide ? !columnsToHide.includes(column.name) : true,
        }),
      );
      bufferTableStore.filterColumns();
    },
    formatUserCriteria(): string {
      this.startDateSelected = [this.startDate];
      this.endDateSelected = [this.endDate];
      const filterTypes = [
        { type: 'customer', values: this.customersSelected },
        {
          type: 'destination-location',
          values: this.destinationLocationSelected,
        },
        { type: 'end-date', values: this.endDateSelected },
        { type: 'material', values: this.materialsSelected },
        { type: 'neo-status', values: this.neoStatusSelected },
        { type: 'buffer-status', values: this.bufferStatusSelected },
        { type: 'outbound-delivery', values: this.outboundDeliverySelected },
        { type: 'source-location', values: this.sourceLocationSelected },
        { type: 'start-date', values: this.startDateSelected },
        { type: 'work-center', values: this.workCentersSelected },
        { type: 'order-id', values: this.orderIdSelected.trim() },
        { type: 'action-type', values: this.actionTypesSelected },
      ];

      return filterTypes
        .map((filter): string => {
          return filter.values.length > 0
            ? ((): string => {
                const values = Array.isArray(filter.values)
                  ? filter.values.join(',')
                  : filter.values;
                return `${filter.type}:${values}`;
              })()
            : '';
        })
        .filter((criteria) => criteria !== '') // Include selected filters
        .join(';');
    },
    async getFilterSelections() {
      const data = (await api.getFilterSelectionList()) as {
        actionTypeList: Array<string>;
        bufferStatusList: Array<string>;
        shopOrderList: Array<string>;
        customerList: Array<string>;
        destinationLocationList: Array<string>;
        materialList: Array<string>;
        neoStatusList: Array<string>;
        odList: Array<string>;
        sourceLocationList: Array<string>;
        workcenterList: Array<string>;
      };

      this.actionTypeList = data.actionTypeList || [];
      this.bufferStatusList = data.bufferStatusList || [];
      this.shopOrderList = data.shopOrderList || [];
      this.customerList = data.customerList || [];
      this.neoStatusList = [...(data.neoStatusList ?? []), ' '];
      this.destinationLocationList = data.destinationLocationList || [];
      this.sourceLocationList = data.sourceLocationList || [];
      this.materialList = data.materialList || [];
      this.workcenterList = data.workcenterList || [];
      this.outboudDeliveryList = data.odList || [];
    },

    resetFilter() {
      this.actionTypesSelected.length = 0;
      this.workCentersSelected.length = 0;
      this.materialsSelected.length = 0;
      this.sourceLocationSelected.length = 0;
      this.destinationLocationSelected.length = 0;
      this.neoStatusSelected.length = 0;
      this.bufferStatusSelected.length = 0;
      this.customersSelected.length = 0;
      this.orderIdSelected = '';
      this.outboundDeliverySelected.length = 0;
      this.startDate = '';
      this.endDate = '';
      this.startDateSelected.length = 0;
      this.shopOrdersSelected.length = 0;
      this.endDateSelected.length = 0;
    },

    // Save filter preferences function
    async saveFilterPreferences() {
      const bufferTableStore = useBufferTableStore();
      bufferTableStore.displayFilter = false;
      const userProfile = useUserAttributesStore();
      const plant = Number(userProfile.userAttributes.plant);
      const userCriteria = this.formatUserCriteria();
      const userId = localStorage.getItem('userId') ?? 'undefined';
      const preferenceData: UserPreference = {
        userCriteria,
        action: 'FILTER',
        appName: 'BUFFER-MONITORING',
        plant,
        user: { userId },
      };
      try {
        const result = await api.saveUserPreferences([preferenceData]);
        await bufferTableStore.fetchBufferTableData({ resetPage: true });
        return result;
      } catch (error) {
        console.error('Error saving preferences:', error);
        throw error;
      }
    },
  },
  id: 'filters',
  state: () => ({
    actionTypeList: [] as Array<string>,
    actionTypesSelected: [] as Array<string>,
    bufferStatusList: [] as Array<string>,
    bufferStatusSelected: [] as Array<string>,
