  authorizeUser,
  AuthConfigService,
  ApiService,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
import { useRouter } from 'vue-router';
import { useUserStore } from './user-store.ts';
import { configuration } from '@/Auth/configuration.ts';
import { getUser, User } from '@/Auth/user-service.ts';
import { AuthConfigDTO } from '@/types/auth.config.dto.ts';
import appLogger from '@/utils/logger/app-logger';

interface State {
  profile: string;
  user: User | undefined;
  userAttributes: { [key: string]: string };
}

const authconfig = new AuthConfigDTO(
  configuration.getAuthority(),
  configuration.getClientId(),
  configuration.getRedirectUri(),
  configuration.getResponseType(),
  configuration.getScopes(),
  new WebStorageStateStore({ store: window.sessionStorage }),
  configuration.getAccessTokenExpiringNotificationTime(),
);
const umeBaseUrl = import.meta.env.UME_API_URL;
const appName = 'BUFFER-MONITORING';
const tokenEnvironment = import.meta.env.TOKEN;
const pickingRedirectUri = import.meta.env.PICKING_APP_REDIRECT_URI;
let appBasePath: string;
if (pickingRedirectUri) {
  const parts = pickingRedirectUri.split('/');
  appBasePath = parts.pop();
}
const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, tokenEnvironment, appName);
const userAttributesManager = new UserAttributesManager(apiService);
export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      if (user) {
        const fetchedUser = await apiService.getUserByEmail(user.profile.email);
        if (fetchedUser) {
          localStorage.setItem('userId', fetchedUser.userId);
          await apiService.updateUserLastLoginByEmail(
            fetchedUser.email,
            new Date(),
          );
        } else {
          const userDetails = {
            firstName: user.profile.given_name,
            lastName: user.profile.family_name,
            email: user.profile.email,
            lastLogin: new Date(),
          };
          await apiService.saveUser(userDetails);
        }
        useUser.setProfile(
          `${user.profile.given_name} ${user.profile.family_name}`,
        );
      }
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes =
          userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes) {
          this.userAttributes = { ...userAttributes };
        } else {
          appLogger.warn('No user attributes found.');
        }
      } catch (error) {
        appLogger.error(`Error fetching user attributes: ${error}`);
      }
    },
    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        await authService.logout();
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
      } catch {
        appLogger.error('Log out failed');
      }
    },
  },

  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    profile: '',
    userAttributes: {} as { [key: string]: string },
    user: undefined as User | undefined,
  }),
});

import { defineStore } from 'pinia';
import { useBufferTableStore } from './buffer-table-store.ts';
import { UserAttribute } from '@/types/user-attribute-type.ts';

export const useUserAttributesStore = defineStore('userAttributes', {
  actions: {
    setUserAttributes(attributes: Array<UserAttribute>) {
      const transformedAttributes =
        this.transformAttributesToStorageFormat(attributes);
      this.userAttributes = transformedAttributes;
      const bufferTableStore = useBufferTableStore();
      bufferTableStore.getPlantById();
    },
    transformAttributesToStorageFormat(attributes: Array<UserAttribute>): {
      [key: string]: string;
    } {
      const transformed: { [key: string]: string } = {};
      for (const attribute of attributes) {
        transformed[attribute.userAttributeName] = attribute.value;
      }
      return transformed;
    },
  },
  persist: true,
  state: () => ({
    userAttributes: {} as { [key: string]: string },
  }),
});

